#include "sim/typed/replay_recording.h"
#include <fstream>
#include <iostream>
using namespace pvz::typed72;
namespace {using J=WireObject;
J run(const J& input,const std::filesystem::path& root){std::filesystem::create_directories(root);ReplayLogLimits limits{input.value("entries",size_t(4)),input.value("bytes",size_t(128)),input.value("record",size_t(1024))};ReplayJournal log(limits,root);J output=J::array();std::filesystem::path storage;for(const auto& op:input.at("operations")){std::string error;J extra=J::object();try{const auto kind=op.at("op").get<std::string>();if(kind=="append")log.append(op.at("event"));else if(kind=="export"){const auto path=root/"recording.json";export_replay_journal(path,op.value("metadata",J::object()),log);std::ifstream file(path,std::ios::binary);extra["exported"]=J::parse(file);}else if(kind=="corrupt"){storage=log.storage_path();std::ofstream file(storage/"part-00000000.jsonl",std::ios::binary);file<<op.at("text").get<std::string>();}else if(kind=="close"){storage=log.storage_path();log.close();extra["storage_removed"]=storage.empty()||!std::filesystem::exists(storage);}else if(kind=="visit_append"){bool done=false;J seen=J::array();log.visit([&](const std::string& line){seen.push_back(J::parse(line));if(!done){done=true;log.append(op.at("event"));}});extra["iterated"]=seen;}else if(kind!="inspect")throw std::invalid_argument("unknown probe op");}catch(const std::exception& e){error=e.what();}
    J rows=J::array();if(!log.closed())try{log.visit([&](const std::string& line){rows.push_back(J::parse(line));});}catch(const std::exception& e){if(error.empty())error=e.what();}J row={{"count",log.size()},{"buffered",log.buffered_count()},{"bytes",log.buffered_bytes()},{"spooled",log.spooled_count()},{"closed",log.closed()},{"failed",!log.error().empty()},{"operation_failed",!error.empty()},{"events",rows}};for(const auto& [key,value]:extra.items())row[key]=value;output.push_back(row);}return output;}
}
int main(int argc,char** argv){try{if(argc!=4)throw std::invalid_argument("expected input output storage-root");std::ifstream in(argv[1],std::ios::binary);std::ofstream out(argv[2],std::ios::binary);std::string line;size_t index=0;while(std::getline(in,line))if(!line.empty())out<<run(J::parse(line),std::filesystem::path(argv[3])/std::to_string(index++)).dump()<<'\n';return in.bad()||!out?2:0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
